//! Keep track of the location of tabstops.
//!
//! This is implemented as a bit set. There is a preallocation segment that
//! is used for almost all screen sizes. Then there is a dynamically allocated
//! segment if the screen is larger than the preallocation amount.
//!
//! In reality, tabstops don't need to be the most performant in any metric.
//! This implementation tries to balance denser memory usage (by using a bitset)
//! and minimizing unnecessary allocations.
pub fn init(alloc: Allocator, cols: usize, interval: usize) Allocator.Error!Tabstops
pub fn deinit(self: *Tabstops, alloc: Allocator) void
pub fn set(self: *Tabstops, col: usize) void — Set the tabstop at a certain column. The columns are 0-indexed.
pub fn unset(self: *Tabstops, col: usize) void — Unset the tabstop at a certain column. The columns are 0-indexed.
pub fn get(self: Tabstops, col: usize) bool — Get the value of a tabstop at a specific column. The columns are 0-indexed.
pub fn resize(self: *Tabstops, alloc: Allocator, cols: usize) Allocator.Error!void
pub fn capacity(self: Tabstops) usize — Return the maximum number of columns this can support currently.
pub fn reset(self: *Tabstops, interval: usize) void — Unset all tabstops and then reset the initial tabstops to the given interval. An interval of 0 sets no tabstops.

